// angle indexes
#define	PITCH				0		// up / down
#define	YAW					1		// left / right
#define	ROLL				2		// fall over

typedef float vec_t;
typedef vec_t vec3_t[3];
typedef vec_t vec5_t[5];

typedef	int	fixed4_t;
typedef	int	fixed8_t;
typedef	int	fixed16_t;

#ifndef M_PI
#define M_PI		3.14159265358979323846	// matches value in gcc v2 math.h
#endif

vec3_t vec3_origin = {0,0,0};

#define	nanmask (255<<23)
#define	IS_NAN(x) (((*(int *)&x)&nanmask)==nanmask)

#define Q_ftol(f) (long)(f)
#define DEG2RAD(a) ((a * M_PI ) / 180.0F)

#define DotProduct(x, y)		(x[0]*y[0] + x[1]*y[1] + x[2]*y[2])
#define VectorSubtract(a, b, c)	(c[0]=a[0]-b[0], c[1]=a[1]-b[1], c[2]=a[2]-b[2])
#define VectorAdd(a, b, c)		(c[0]=a[0]+b[0], c[1]=a[1]+b[1], c[2]=a[2]+b[2])
#define VectorCopy(a, b)		(b[0]=a[0], b[1]=a[1], b[2]=a[2])
#define VectorClear(a)			(a[0]=a[1]=a[2]=0)
#define VectorNegate(a, b)		(b[0]=-a[0], b[1]=-a[1], b[2]=-a[2])
#define VectorSet(v, x, y, z)	(v[0]=(x), v[1]=(y), v[2]=(z))

static void VectorMA(vec3_t veca, float scale, vec3_t vecb, vec3_t vecc) {
	vecc[0] = veca[0] + scale*vecb[0];
	vecc[1] = veca[1] + scale*vecb[1];
	vecc[2] = veca[2] + scale*vecb[2];
}

static void AddPointToBounds(vec3_t v, vec3_t mins, vec3_t maxs) {
	for (int i = 0; i < 3; i++) {
		vec_t val = v[i];
		if (val < mins[i]) {
			mins[i] = val;
		}
		if (val > maxs[i]) {
			maxs[i] = val;
		}
	}
}

static int VectorCompare(vec3_t v1, vec3_t v2) {
	if (v1[0] != v2[0] || v1[1] != v2[1] || v1[2] != v2[2]) {
		return 0;
	}
	return 1;
}

static vec_t VectorLength(vec3_t v) {
	vec_t length_squared = 0;
	for (int i = 0; i < 3; i++) {
		length_squared += v[i]*v[i];
	}
	vec_t length = sqrt(length_squared);
	return length;
}

static void CrossProduct(vec3_t v1, vec3_t v2, vec3_t cross) {
	cross[0] = v1[1]*v2[2] - v1[2]*v2[1];
	cross[1] = v1[2]*v2[0] - v1[0]*v2[2];
	cross[2] = v1[0]*v2[1] - v1[1]*v2[0];
}

static vec_t VectorNormalize(vec3_t v) {
	float length_squared = v[0]*v[0] + v[1]*v[1] + v[2]*v[2];
	float length = sqrt(length_squared);
	if (length) {
		float ilength = 1 / length;
		v[0] *= ilength;
		v[1] *= ilength;
		v[2] *= ilength;
	}
	return length;
}

static void VectorScale(vec3_t in, vec_t scale, vec3_t out) {
	out[0] = in[0] * scale;
	out[1] = in[1] * scale;
	out[2] = in[2] * scale;
}

static void R_ConcatRotations(float in1[3][3], float in2[3][3], float out[3][3]) {
	out[0][0] = in1[0][0] * in2[0][0] + in1[0][1] * in2[1][0] + in1[0][2] * in2[2][0];
	out[0][1] = in1[0][0] * in2[0][1] + in1[0][1] * in2[1][1] + in1[0][2] * in2[2][1];
	out[0][2] = in1[0][0] * in2[0][2] + in1[0][1] * in2[1][2] + in1[0][2] * in2[2][2];
	out[1][0] = in1[1][0] * in2[0][0] + in1[1][1] * in2[1][0] + in1[1][2] * in2[2][0];
	out[1][1] = in1[1][0] * in2[0][1] + in1[1][1] * in2[1][1] + in1[1][2] * in2[2][1];
	out[1][2] = in1[1][0] * in2[0][2] + in1[1][1] * in2[1][2] + in1[1][2] * in2[2][2];
	out[2][0] = in1[2][0] * in2[0][0] + in1[2][1] * in2[1][0] + in1[2][2] * in2[2][0];
	out[2][1] = in1[2][0] * in2[0][1] + in1[2][1] * in2[1][1] + in1[2][2] * in2[2][1];
	out[2][2] = in1[2][0] * in2[0][2] + in1[2][1] * in2[1][2] + in1[2][2] * in2[2][2];
}

static void AngleVectors(vec3_t angles, vec3_t forward, vec3_t right, vec3_t up) {
	float yaw = DEG2RAD(angles[YAW]);
	float sy = sin(yaw);
	float cy = cos(yaw);

	float pitch = DEG2RAD(angles[PITCH]);
	float sp = sin(pitch);
	float cp = cos(pitch);

	float roll = DEG2RAD(angles[ROLL]);
	float sr = sin(roll);
	float cr = cos(roll);

	if (forward) {
		forward[0] = cp*cy;
		forward[1] = cp*sy;
		forward[2] = -sp;
	}

	if (right) {
		right[0] = (-1*sr*sp*cy+-1*cr*-sy);
		right[1] = (-1*sr*sp*sy+-1*cr*cy);
		right[2] = -1*sr*cp;
	}

	if (up) {
		up[0] = (cr*sp*cy+-sr*-sy);
		up[1] = (cr*sp*sy+-sr*cy);
		up[2] = cr*cp;
	}
}

static float anglemod(float a) {
	a = (360.0/65536) * ((int)(a*(65536/360.0)) & 65535);
	return a;
}

static float LerpAngle (float a2, float a1, float frac) {
	if (a1 - a2 > 180) {
		a1 -= 360;
	}
	if (a1 - a2 < -180) {
		a1 += 360;
	}
	return a2 + frac * (a1 - a2);
}

static void ProjectPointOnPlane(vec3_t dst, const vec3_t p, const vec3_t normal) {
	float inv_denom = 1.0F / DotProduct( normal, normal );
	float d = DotProduct( normal, p ) * inv_denom;

	vec3_t n;
	n[0] = normal[0] * inv_denom;
	n[1] = normal[1] * inv_denom;
	n[2] = normal[2] * inv_denom;

	dst[0] = p[0] - d * n[0];
	dst[1] = p[1] - d * n[1];
	dst[2] = p[2] - d * n[2];
}

// assumes "src" is normalized
static void PerpendicularVector(vec3_t dst, const vec3_t src) {

	// find the smallest magnitude axially aligned vector
	int	pos = 0;
	float minelem = 1.0F;
	for (int i = 0; i < 3; i++) {
		if (fabs( src[i] ) < minelem) {
			pos = i;
			minelem = fabs( src[i] );
		}
	}

	vec3_t tempvec;
	tempvec[0] = tempvec[1] = tempvec[2] = 0.0F;
	tempvec[pos] = 1.0F;

	ProjectPointOnPlane(dst, tempvec, src);
	VectorNormalize(dst);
}

static void RotatePointAroundVector(vec3_t dst, const vec3_t dir, const vec3_t point, float degrees) {
	vec3_t vf = {dir[0], dir[1], dir[2]};

	vec3_t vr;
	PerpendicularVector(vr, dir);

	vec3_t vup;
	CrossProduct(vr, vf, vup);

	float m[3][3];
	m[0][0] = vr[0];
	m[1][0] = vr[1];
	m[2][0] = vr[2];

	m[0][1] = vup[0];
	m[1][1] = vup[1];
	m[2][1] = vup[2];

	m[0][2] = vf[0];
	m[1][2] = vf[1];
	m[2][2] = vf[2];

	float im[3][3];
	memcpy(im, m, sizeof(im));
	im[0][1] = m[1][0];
	im[0][2] = m[2][0];
	im[1][0] = m[0][1];
	im[1][2] = m[2][1];
	im[2][0] = m[0][2];
	im[2][1] = m[1][2];

	float zrot[3][3] = {};
	zrot[0][0] = zrot[1][1] = zrot[2][2] = 1.0F;

	float radians = DEG2RAD(degrees);
	float cos_val = cos(radians);
	float sin_val = sin(radians);
	zrot[0][0] = cos_val;
	zrot[0][1] = sin_val;
	zrot[1][0] = -sin_val;
	zrot[1][1] = cos_val;

	float tmpmat[3][3];
	R_ConcatRotations(m, zrot, tmpmat);

	float rot[3][3];
	R_ConcatRotations(tmpmat, im, rot);

	for (int i = 0; i < 3; i++) {
		dst[i] = rot[i][0] * point[0] + rot[i][1] * point[1] + rot[i][2] * point[2];
	}
}

