static unsigned short CRC_Block(byte* start, int count) {
	unsigned short crc = 0xffff;
	while (count--) {
		crc = (crc << 8) ^ crctable[(crc >> 8) ^ *start++];
	}
	return crc;
}

//
// SECTION Memory
//

#define	Z_MAGIC 0x1d1d

typedef struct zhead_s {
	struct zhead_s* prev;
	struct zhead_s* next;
	short	magic;
	short	tag;	// for group free
	int		size;
} zhead_t;

static zhead_t z_chain;
static int z_count;
static int z_bytes;

static void Z_Free(void *ptr) {
	zhead_t* z = ((zhead_t*)ptr) - 1;
	assert(z->magic == Z_MAGIC);

	z->prev->next = z->next;
	z->next->prev = z->prev;

	z_count--;
	z_bytes -= z->size;
	free(z);
}

static void Z_FreeTags(int tag) {
	for (zhead_t* z = z_chain.next; z != &z_chain;) {
		zhead_t* next = z->next;
		if (z->tag == tag) {
			Z_Free((void *)(z+1));
		}
		z = next;
	}
}

static void* Z_TagMalloc(int size, int tag) {
	size = size + sizeof(zhead_t);
	zhead_t* z = malloc(size);
	assert(z);
	memset (z, 0, size);
	z_count++;
	z_bytes += size;
	z->magic = Z_MAGIC;
	z->tag = tag;
	z->size = size;

	z->next = z_chain.next;
	z->prev = &z_chain;
	z_chain.next->prev = z;
	z_chain.next = z;

	return (void *)(z+1);
}

static void* Z_Malloc(int size) {return Z_TagMalloc(size, 0);}

//
// SECTION Sizebuf
//

typedef struct sizebuf_s {
	qboolean	allowoverflow;	// if false, do a Com_Error
	qboolean	overflowed;		// set to true if the buffer size failed
	byte		*data;
	int			maxsize;
	int			cursize;
	int			readcount;
} sizebuf_t;

static void SZ_Init(sizebuf_t* buf, byte* data, int length) {
	*buf = (sizebuf_t){.data = data, .maxsize = length};
}

static void SZ_Clear(sizebuf_t* buf) {
	buf->cursize = 0;
	buf->overflowed = false;
}

static void* SZ_GetSpace(sizebuf_t* buf, int length) {
	if (buf->cursize + length > buf->maxsize) {
		assert(buf->allowoverflow);
		assert(length <= buf->maxsize);

		buf->cursize = 0;
		buf->overflowed = true;
	}

	void* data = buf->data + buf->cursize;
	buf->cursize += length;
	return data;
}

static void SZ_Write(sizebuf_t* buf, void* data, int length) {
	void* dest = SZ_GetSpace(buf, length);
	memcpy(dest, data, length);
}

static void SZ_Print(sizebuf_t* buf, char* data) {
	int len = strlen(data) + 1; // NOTE: include null terminator

	if (buf->cursize) {
		if (buf->data[buf->cursize - 1]) {
			memcpy((byte*)SZ_GetSpace(buf, len), data, len); // NOTE: no trailing 0 from previous prints
		} else {
			memcpy((byte*)SZ_GetSpace(buf, len - 1) - 1, data, len); // NOTE: write over trailing 0 from previous prints
		}
	} else {
		memcpy((byte*)SZ_GetSpace(buf, len), data, len);
	}
}

//
// SECTION Strings
//

static char* CopyString(char *in) {
	int in_len = strlen(in);
	char* out = Z_Malloc(in_len + 1);
	strcpy(out, in);
	return out;
}

static int Q_strcasecmp(char *s1, char *s2) {
	int n = 99999;
	int	c1 = 0;
	int c2 = 0;
	do {
		c1 = *s1++;
		c2 = *s2++;

		if (!n--) {
			return 0;		// strings are equal until end point
		}

		if (c1 != c2) {
			if (c1 >= 'a' && c1 <= 'z') {
				c1 -= ('a' - 'A');
			}
			if (c2 >= 'a' && c2 <= 'z') {
				c2 -= ('a' - 'A');
			}
			if (c1 != c2) {
				return -1;		// strings not equal
			}
		}
	} while (c1);
	return 0;		// strings are equal
}

static int Q_stricmp(char *s1, char *s2) {return Q_strcasecmp(s1, s2);}

// vsprintf into a sized buffer; the destination is always null-terminated on overflow, which even MSVC's _vsnprintf doesn't guarantee
static int Q_vsnprintf(char *str, size_t size, char *format, va_list ap) {
	int len = vsnprintf(str, size, format, ap);
	str[size-1] = 0;
	return len;
}

// does a varargs printf into a temp buffer, so I don't need to have varargs versions of all text functions.
static char* va(char *format, ...) {
	static char string[1024];
	va_list argptr;
	va_start (argptr, format);
	Q_vsnprintf (string, sizeof(string), format, argptr);
	va_end (argptr);
	return string;
}

