//
// SECTION Con (console)
//

#define	NUM_CON_TIMES 4
#define CON_TEXTSIZE 32768

#define	PRINT_MEDIUM	1	// death messages
#define	PRINT_HIGH		2	// critical messages
#define	PRINT_CHAT		3	// chat messages

static struct {
	qboolean	initialized;
	char		text[CON_TEXTSIZE];
	int			current;		// line where next message will be printed
	int			x;				// offset in current line for next print
	int			display;		// bottom of console displays this line
	int			ormask;			// high bit mask for colored characters
	int 		linewidth;		// characters across screen
	int			totallines;		// total lines in console scrollback
	float		cursorspeed;
	int			vislines;
	float		times[NUM_CON_TIMES];	// cls.realtime time the line was generated
} con;

// Handles cursor positioning, line wrapping, etc
// All console printing must go through this in order to be logged to disk
// If no console is visible, the text will appear at the top of the game window
static void Con_Print(char *txt) {
	static int cr = false;

	if (!con.initialized) {
		return;
	}

	int mask = 0;
	if (txt[0] == 1 || txt[0] == 2) {
		int colored_text_mask = 128;
		mask = colored_text_mask;
		txt++;
	}

	int c = 0;
	while ((c = *txt)) {
		// count word length
		int l = 0;
		for (l = 0; l < con.linewidth; l++) {
			if (txt[l] <= ' ') {
				break;
			}
		}

		// word wrap
		if (l != con.linewidth && (con.x + l > con.linewidth)) {
			con.x = 0;
		}

		txt++;

		if (cr) {
			con.current--;
			cr = false;
		}

		if (!con.x) {
			// Linefeed
			{
				con.x = 0;
				if (con.display == con.current) {
					con.display++;
				}
				con.current++;
				memset(&con.text[(con.current%con.totallines)*con.linewidth], ' ', con.linewidth);
			}

			// mark time for transparent overlay
			if (con.current >= 0) {
				con.times[con.current % NUM_CON_TIMES] = cls.realtime;
			}
		}

		switch (c) {
		case '\n': {
			con.x = 0;
		} break;

		case '\r': {
			con.x = 0;
			cr = 1;
		} break;

		// display character and advance
		default: {
			int y = con.current % con.totallines;
			con.text[y*con.linewidth + con.x] = c | mask | con.ormask;
			con.x++;
			if (con.x >= con.linewidth) {
				con.x = 0;
			}
		} break;
		}
	}
}

//
// SECTION COM (commands)
//

#define	MAXPRINTMSG		4096
#define MAX_NUM_ARGVS	50
#define	MAX_TOKEN_CHARS	128		// max length of an individual token

#define	MAX_QPATH 64 // max length of a quake game pathname

static int		rd_target;
static char*	rd_buffer;
static int		rd_buffersize;
static void		(*rd_flush)(int target, char *buffer);

static cvar_t*	logfile_active; // 1 = buffer log, 2 = flush after each print
static FILE*	logfile;

static int		com_argc;
static char*	com_argv[MAX_NUM_ARGVS + 1];

static char com_token[MAX_TOKEN_CHARS];

static void COM_StripExtension(char* in, char* out) {
	while (*in && *in != '.') {
		*out++ = *in++;
	}
	*out = 0;
}

static void COM_FilePath(char *in, char *out) {
	char* s = in + strlen(in) - 1;
	while (s != in && *s != '/') {
		s--;
	}
	strncpy(out, in, s-in);
	out[s-in] = 0;
}

static void Com_sprintf(char *dest, int size, char *fmt, ...) {
	char bigbuffer[0x10000];
	va_list argptr;
	va_start(argptr, fmt);
	int len = vsprintf (bigbuffer, fmt, argptr);
	va_end (argptr);
	assert(len < size);
	strncpy (dest, bigbuffer, size-1);
}

// Both client and server can use this, and it will output
// to the apropriate place.
static void Com_Printf(char *fmt, ...) {
	char msg[MAXPRINTMSG];
	va_list argptr;
	va_start(argptr, fmt);
	Q_vsnprintf(msg, sizeof(msg), fmt, argptr);
	va_end(argptr);

	if (rd_target) {
		if ((strlen(msg) + strlen(rd_buffer)) > (rd_buffersize - 1)) {
			rd_flush(rd_target, rd_buffer);
			*rd_buffer = 0;
		}
		strcat(rd_buffer, msg);
		return;
	}

	Con_Print(msg);

	// logfile
	if (logfile_active && logfile_active->value) {
		char name[MAX_QPATH];

		if (!logfile) {
			Com_sprintf(name, sizeof(name), "%s/qconsole.log", FS_Gamedir());
			logfile = fopen (name, "w");
		}

		if (logfile) {
			fprintf (logfile, "%s", msg);
		}

		if (logfile_active->value > 1) {
			fflush (logfile); // force it to save every time
		}
	}
}

// Parse a token out of a string
// data is an in/out parm, returns a parsed out token
static char* COM_Parse(char** data_p) {
	char* data = *data_p;
	int len = 0;
	com_token[0] = 0;

	if (!data)
	{
		*data_p = NULL;
		return "";
	}

	int c = *data;

	// skip whitespace
	skipwhite:
	while ((c = *data) <= ' ') {
		if (c == 0) {
			*data_p = NULL;
			return "";
		}
		data++;
	}

	// skip // comments
	if (c=='/' && data[1] == '/') {
		while (*data && *data != '\n') {
			data++;
		}
		goto skipwhite;
	}

	// handle quoted strings specially
	if (c == '\"') {
		data++;
		for (;;) {
			c = *data++;
			if (c=='\"' || !c) {
				com_token[len] = 0;
				*data_p = data;
				return com_token;
			}
			if (len < MAX_TOKEN_CHARS) {
				com_token[len] = c;
				len++;
			}
		}
	}

	// parse a regular word
	do {
		if (len < MAX_TOKEN_CHARS) {
			com_token[len] = c;
			len++;
		}
		data++;
		c = *data;
	} while (c > 32);

	if (len == MAX_TOKEN_CHARS) {
		Com_Printf ("Token exceeded %i chars, discarded.\n", MAX_TOKEN_CHARS);
		len = 0;
	}
	com_token[len] = 0;

	*data_p = data;
	return com_token;
}

static char* COM_Argv(int arg) {
	if (arg < 0 || arg >= com_argc || !com_argv[arg]) {
		return "";
	}
	return com_argv[arg];
}

static void COM_ClearArgv(int arg) {
	if (arg < 0 || arg >= com_argc || !com_argv[arg]) {
		return;
	}
	com_argv[arg] = "";
}

static void COM_InitArgv(int argc, char **argv) {
	assert(argc <= MAX_NUM_ARGVS);
	com_argc = argc;
	for (int i = 0; i < argc; i++) {
		if (!argv[i] || strlen(argv[i]) >= MAX_TOKEN_CHARS) {
			com_argv[i] = "";
		} else {
			com_argv[i] = argv[i];
		}
	}
}

// creates the variable if it doesn't exist, or returns the existing one
// if it exists, the value will not be changed, but flags will be ORed in
// that allows variables to be unarchived without needing bitflags
static cvar_t* COM_GetCvar(char* var_name, char* var_value, int flags) {
	if (flags & (CVAR_USERINFO | CVAR_SERVERINFO)) {
		if (!Cvar_InfoValidate(var_name)) {
			Com_Printf("invalid info cvar name\n");
			return NULL;
		}
	}

	cvar_t* var = Cvar_FindVar(var_name);
	if (var) {
		var->flags |= flags;
		return var;
	}

	if (!var_value) {
		return NULL;
	}

	if (flags & (CVAR_USERINFO | CVAR_SERVERINFO)) {
		if (!Cvar_InfoValidate (var_value)) {
			Com_Printf("invalid info cvar value\n");
			return NULL;
		}
	}

	var = Z_Malloc(sizeof(*var));
	var->name = CopyString(var_name);
	var->string = CopyString(var_value);
	var->modified = true;
	var->value = atof(var->string);

	// link the variable in
	var->next = cvar_vars;
	cvar_vars = var;

	var->flags = flags;
	return var;
}

// will create the variable if it doesn't exist
// will set the variable even if NOSET or LATCH when force = true
static cvar_t* COM_SetCvar_(char* var_name, char* value, qboolean force) {
	cvar_t* var = Cvar_FindVar (var_name);
	if (!var) {
		// create it
		return COM_GetCvar(var_name, value, 0);
	}

	if (var->flags & (CVAR_USERINFO | CVAR_SERVERINFO)) {
		if (!Cvar_InfoValidate (value)) {
			Com_Printf("invalid info cvar value\n");
			return var;
		}
	}

	if (!force) {
		if (var->flags & CVAR_NOSET) {
			Com_Printf("%s is write protected.\n", var_name);
			return var;
		}

		if (var->flags & CVAR_LATCH) {
			if (var->latched_string) {
				if (strcmp(value, var->latched_string) == 0) {
					return var;
				}
				Z_Free (var->latched_string);
			} else {
				if (strcmp(value, var->string) == 0) {
					return var;
				}
			}

			if (server_state) {
				Com_Printf("%s will be changed for next game.\n", var_name);
				var->latched_string = CopyString(value);
			} else {
				var->string = CopyString(value);
				var->value = atof (var->string);
				if (!strcmp(var->name, "game"))
				{
					FS_SetGamedir (var->string);
					FS_ExecAutoexec ();
				}
			}
			return var;
		}
	} else {
		if (var->latched_string) {
			Z_Free (var->latched_string);
			var->latched_string = NULL;
		}
	}

	if (!strcmp(value, var->string)) {
		// not changed
		return var;
	}

	var->modified = true;

	if (var->flags & CVAR_USERINFO) {
		// transmit at next oportunity
		userinfo_modified = true;
	}

	// free the old value string
	Z_Free (var->string);

	var->string = CopyString(value);
	var->value = atof (var->string);

	return var;
}

static cvar_t* COM_SetCvar(char* var_name, char* value)		{return COM_SetCvar_(var_name, value, false);}
static cvar_t* Com_ForceSetCvar(char *var_name, char *value)	{return COM_SetCvar_(var_name, value, true);}

static cvar_t* COM_FullSetCvar(char* var_name, char* value, int flags) {
	cvar_t* var = Cvar_FindVar(var_name);
	if (!var) {
		// create it
		return COM_GetCvar(var_name, value, flags);
	}

	var->modified = true;

	if (var->flags & CVAR_USERINFO) {
		// transmit at next oportunity
		userinfo_modified = true;
	}

	// free the old value string
	Z_Free (var->string);

	var->string = CopyString(value);
	var->value = atof (var->string);
	var->flags = flags;

	return var;
}

// converts value to string and sets as normal
static void COM_SetValueCvar(char *var_name, float value) {
	char val[32] = {};
	if (value == (int)value) {
		Com_sprintf (val, sizeof(val), "%i", (int)value);
	} else {
		Com_sprintf (val, sizeof(val), "%f", value);
	}
	COM_SetCvar (var_name, val);
}

void 		Com_DPrintf (char *fmt, ...);
void 		Com_Error (int code, char *fmt, ...);
void 		Com_Quit (void);

int			Com_ServerState (void);		// this should have just been a cvar...
void		Com_SetServerState (int state);

unsigned	Com_BlockChecksum (void *buffer, int length);
byte		COM_BlockSequenceCRCByte (byte *base, int length, int sequence);

//
// SECTION Cbuf (command buffer)
//

// Any number of commands can be added in a frame, from several different sources.
// Most commands come from either keybindings or console line input, but remote
// servers can also send across commands and entire text files can be execed.
// The + command line options are also added to the command buffer.
// The game starts with a Cbuf_AddText("exec quake.rc\n"); Cmd_ExecuteCbuf();

static sizebuf_t	cmd_text;
static byte			cmd_text_buf[8192];

// Used to defer any pending commands while a map is being loaded
static char defer_text_buf[8192];

// as new commands are generated from the console or keybindings, the text is added to the end of the command buffer.
static void Cbuf_AddText(char* text) {
	int l = strlen (text);
	if (cmd_text.cursize + l >= cmd_text.maxsize) {
		Com_Printf("Cbuf_AddText: overflow\n");
		return;
	}
	SZ_Write(&cmd_text, text, l);
}

// When a command wants to issue other commands immediately, the text is
// inserted at the beginning of the buffer, before any remaining unexecuted
// commands.
// Adds a \n to the text
// FIXME: actually change the command buffer to do less copying
static void Cbuf_InsertText(char* text) {
	char* temp = 0;

	// copy off any commands still remaining in the exec buffer
	int templen = cmd_text.cursize;
	if (templen) {
		temp = Z_Malloc(templen);
		memcpy(temp, cmd_text.data, templen);
		SZ_Clear(&cmd_text);
	}

	// add the entire text of the file
	Cbuf_AddText(text);

	// add the copied off data
	if (templen) {
		SZ_Write(&cmd_text, temp, templen);
		Z_Free(temp);
	}
}

// Adds command line parameters as script statements
// Commands lead with a +, and continue until another +
// Set commands are added early, so they are guaranteed to be set before the client and server initialize for the first time.
// Other commands are added late, after all initialization is complete.
static void Cbuf_AddEarlyCommands(qboolean clear) {
	for (int i = 0; i < com_argc; i++) {
		char* s = COM_Argv(i);
		if (strcmp (s, "+set")) {
			continue;
		}
		Cbuf_AddText(va("set %s %s\n", COM_Argv(i + 1), COM_Argv(i + 2)));
		if (clear) {
			COM_ClearArgv(i);
			COM_ClearArgv(i+1);
			COM_ClearArgv(i+2);
		}
		i+=2;
	}
}

// Adds command line parameters as script statements
// Commands lead with a + and continue until another + or -
// quake +vid_ref gl +map amlev1
// Returns true if any late commands were added, which will keep the demoloop from immediately starting
static qboolean Cbuf_AddLateCommands() {
	// build the combined string to parse from
	int s = 0;
	int argc = com_argc;
	for (int i=1 ; i<argc ; i++) {
		s += strlen(COM_Argv(i)) + 1;
	}
	if (!s) {
		return false;
	}

	char* text = Z_Malloc(s+1);
	text[0] = 0;
	for (int i=1 ; i<argc ; i++) {
		strcat(text, COM_Argv(i));
		if (i != argc-1) {
			strcat(text, " ");
		}
	}

	// pull out the commands
	char* build = Z_Malloc(s+1);
	build[0] = 0;

	for (int i=0; i < s - 1; i++) {
		if (text[i] == '+') {
			i++;

			int j = i;
			while ((text[j] != '+') && (text[j] != '-') && (text[j] != 0)) {j++;}

			char c = text[j];
			text[j] = 0;

			strcat(build, text+i);
			strcat(build, "\n");
			text[j] = c;
			i = j-1;
		}
	}

	qboolean ret = (build[0] != 0);
	if (ret) {
		Cbuf_AddText(build);
	}

	Z_Free(text);
	Z_Free(build);

	return ret;
}

//
// SECTION Cmd (command execution)
//

// Command execution takes a null terminated string, breaks it into tokens,
// then searches for a command or variable that matches the first token.

#define	MAX_STRING_CHARS	1024	// max length of a string passed to Cmd_TokenizeString
#define	MAX_STRING_TOKENS	80		// max tokens resulting from Cmd_TokenizeString
#define	MAX_ALIAS_NAME		32
#define	ALIAS_LOOP_COUNT	16

typedef void (*xcommand_t)(void);

typedef struct cmd_function_s {
	struct cmd_function_s*	next;
	char*					name;
	xcommand_t				function;
} cmd_function_t;

typedef struct cmdalias_s {
	struct cmdalias_s*	next;
	char	name[MAX_ALIAS_NAME];
	char*	value;
} cmdalias_t;

// Functions that execute commands get the parameters from here
static	int		cmd_argc;
static	char*	cmd_argv[MAX_STRING_TOKENS];

// a single string containing argv(1) to argv(argc()-1)
static	char	cmd_args[MAX_STRING_CHARS];

// Causes execution of the remainder of the command buffer to be delayed until next frame.
// This allows commands like:
// bind g "impulse 5 ; +attack ; wait ; -attack ; impulse 2"
static qboolean cmd_wait;

static cmd_function_t*	cmd_functions;	// possible commands to execute
static cmdalias_t*		cmd_alias;
static int 				alias_count;	// for detecting runaway loops

static int Cmd_Argc() {return cmd_argc;}

static char* Cmd_Argv(int arg) {
	if ((unsigned)arg >= cmd_argc) {
		return "";
	}
	return cmd_argv[arg];
}

static char* Cmd_Args() {return cmd_args;}

// Parses the given string into command line tokens.
// $Cvars will be expanded unless they are in a quoted token
// Takes a null terminated string. Does not need to be /n terminated.
static void Cmd_TokenizeString(char* text, qboolean macroExpand) {
	// clear the args from the last string
	for (int i = 0; i < cmd_argc; i++) {
		Z_Free (cmd_argv[i]);
	}

	cmd_argc = 0;
	cmd_args[0] = 0;

	// macro expand the text
	if (macroExpand) {
		static char expanded[MAX_STRING_CHARS] = {};
		char temporary[MAX_STRING_CHARS] = {};

		qboolean inquote = false;
		char* scan = text;

		int len = strlen(scan);
		if (len >= MAX_STRING_CHARS) {
			Com_Printf("Line exceeded %i chars, discarded.\n", MAX_STRING_CHARS);
			return;
		}

		int count = 0;

		for (int i = 0; i < len; i++) {
			if (scan[i] == '"') {
				inquote ^= 1;
			}

			if (inquote) {
				// don't expand inside quotes
				continue;
			}

			if (scan[i] != '$') {
				continue;
			}

			// scan out the complete macro
			char* start = scan + i + 1;
			char* token = COM_Parse(&start);
			if (!start) {
				continue;
			}

			token = Cvar_VariableString(token);

			int j = strlen(token);
			len += j;
			if (len >= MAX_STRING_CHARS) {
				Com_Printf ("Expanded line exceeded %i chars, discarded.\n", MAX_STRING_CHARS);
				return;
			}

			strncpy(temporary, scan, i);
			strcpy(temporary + i, token);
			strcpy(temporary + i + j, start);

			strcpy(expanded, temporary);
			scan = expanded;
			i--;

			if (++count == 100) {
				Com_Printf ("Macro expansion loop, discarded.\n");
				return;
			}
		}

		if (inquote) {
			Com_Printf("Line has unmatched quote, discarded.\n");
			return;
		}

		text = scan;
	}

	for (;;) {
		// skip whitespace up to a /n
		while (*text && *text <= ' ' && *text != '\n') {text++;}

		if (*text == '\n') {
			// a newline seperates commands in the buffer
			text++;
			break;
		}

		if (!*text) {
			return;
		}

		// set cmd_args to everything after the first arg
		if (cmd_argc == 1) {
			strcpy (cmd_args, text);

			// strip off any trailing whitespace
			for (int l = strlen(cmd_args) - 1; l >= 0; l--) {
				if (cmd_args[l] <= ' ') {
					cmd_args[l] = 0;
				} else {
					break;
				}
			}
		}

		char* com_token = COM_Parse(&text);
		if (!text) {
			return;
		}

		if (cmd_argc < MAX_STRING_TOKENS) {
			cmd_argv[cmd_argc] = Z_Malloc(strlen(com_token) + 1);
			strcpy(cmd_argv[cmd_argc], com_token);
			cmd_argc++;
		}
	}

}

// Parses a single line of text into arguments and tries to execute it as if it was typed at the console
// FIXME: lookupnoadd the token to speed search?
static void Cmd_ExecuteString(char* text) {
	Cmd_TokenizeString(text, true);

	// execute the command line
	if (!cmd_argc) {
		return; // no tokens
	}

	// check functions
	for (cmd_function_t* cmd = cmd_functions; cmd; cmd = cmd->next) {
		if (!Q_strcasecmp(cmd_argv[0],cmd->name)) {
			if (!cmd->function) {
				// forward to server command
				Cmd_ExecuteString(va("cmd %s", text));
			} else {
				cmd->function();
			}
			return;
		}
	}

	// check alias
	for (cmdalias_t* a = cmd_alias; a; a = a->next) {
		if (!Q_strcasecmp (cmd_argv[0], a->name)) {
			if (++alias_count == ALIAS_LOOP_COUNT) {
				Com_Printf ("ALIAS_LOOP_COUNT\n");
				return;
			}
			Cbuf_InsertText(a->value);
			return;
		}
	}

	// check cvar
	{
		cvar_t* v = Cvar_FindVar(Cmd_Argv(0));
		if (v) {
			if (cmd_argc == 1) {
				Com_Printf("\"%s\" is \"%s\"\n", v->name, v->string);
			} else {
				COM_SetCvar(v->name, Cmd_Argv(1));
			}
			return;
		}
	}

	// send it as a server command if we are connected
	{
		char* cmd = Cmd_Argv(0);

		if (cls.state <= ca_connected || *cmd == '-' || *cmd == '+') {
			Com_Printf ("Unknown command \"%s\"\n", cmd);
			return;
		}

		MSG_WriteByte(&cls.netchan.message, clc_stringcmd);
		SZ_Print(&cls.netchan.message, cmd);
		if (cmd_argc > 1) {
			SZ_Print (&cls.netchan.message, " ");
			SZ_Print (&cls.netchan.message, cmd_args);
		}
	}
}

// Pulls off \n terminated lines of text from the command buffer and sends them through Cmd_ExecuteString.
// Stops when the buffer is empty.
// Normally called once per frame, but may be explicitly invoked.
// Do not call inside a command function!
static void Cmd_ExecuteCbuf() {
	char line[1024] = {};

	alias_count = 0; // don't allow infinite alias loops

	while (cmd_text.cursize) {
		// find a \n or ; line break
		char* text = (char*)cmd_text.data;

		int quotes = 0;
		int i = 0;
		for (; i < cmd_text.cursize; i++) {
			if (text[i] == '"') {
				quotes++;
			}
			if (!(quotes&1) &&  text[i] == ';') {
				break;	// don't break if inside a quoted string
			}
			if (text[i] == '\n') {
				break;
			}
		}

		memcpy (line, text, i);
		line[i] = 0;

		// delete the text from the command buffer and move remaining commands down
		// this is necessary because commands (exec, alias) can insert data at the
		// beginning of the text buffer

		if (i == cmd_text.cursize) {
			cmd_text.cursize = 0;
		} else {
			i++;
			cmd_text.cursize -= i;
			memmove (text, text+i, cmd_text.cursize);
		}

		// execute the command line
		Cmd_ExecuteString(line);

		if (cmd_wait) {
			// skip out while text still remains in buffer, leaving it for next frame
			cmd_wait = false;
			break;
		}
	}
}

// called by the init functions of other parts of the program to register commands and functions to call for them.
// The cmd_name is referenced later, so it should not be in temp memory
// if function is NULL, the command will be forwarded to the server as a clc_stringcmd instead of executed locally
static void Cmd_AddCommand(char* cmd_name, xcommand_t function) {
	// fail if the command is a variable name
	if (Cvar_VariableString(cmd_name)[0]) {
		Com_Printf ("Cmd_AddCommand: %s already defined as a var\n", cmd_name);
		return;
	}

	// fail if the command already exists
	for (cmd_function_t* cmd = cmd_functions; cmd; cmd = cmd->next) {
		if (!strcmp (cmd_name, cmd->name)) {
			Com_Printf ("Cmd_AddCommand: %s already defined\n", cmd_name);
			return;
		}
	}

	cmd_function_t* cmd = Z_Malloc(sizeof(cmd_function_t));
	cmd->name = cmd_name;
	cmd->function = function;
	cmd->next = cmd_functions;
	cmd_functions = cmd;
}

static void Cmd_RemoveCommand(char* cmd_name) {
	cmd_function_t** back = &cmd_functions;
	for (;;) {
		cmd_function_t* cmd = *back;
		if (!cmd) {
			Com_Printf("Cmd_RemoveCommand: %s not added\n", cmd_name);
			return;
		}

		if (!strcmp (cmd_name, cmd->name)) {
			*back = cmd->next;
			Z_Free(cmd);
			return;
		}

		back = &cmd->next;
	}
}

static void Cmd_List_f() {
	int i = 0;
	for (cmd_function_t* cmd = cmd_functions; cmd; cmd = cmd->next, i++) {
		Com_Printf("%s\n", cmd->name);
	}
	Com_Printf("%i commands\n", i);
}

static void Cmd_Exec_f() {
	if (cmd_argc != 2) {
		Com_Printf ("exec <filename> : execute a script file\n");
		return;
	}

	char* f = 0;
	int len = FS_LoadFile(Cmd_Argv(1), (void **)&f);
	if (!f) {
		Com_Printf ("couldn't exec %s\n",Cmd_Argv(1));
		return;
	}
	Com_Printf ("execing %s\n",Cmd_Argv(1));

	// the file doesn't have a trailing 0, so we need to copy it off
	char* f2 = Z_Malloc(len + 1);
	memcpy(f2, f, len);
	f2[len] = 0;

	Cbuf_InsertText(f2);

	Z_Free(f2);
	FS_FreeFile(f);
}

// Just prints the rest of the line to the console
static void Cmd_Echo_f() {
	for (int i=1; i < cmd_argc; i++) {
		Com_Printf("%s ", Cmd_Argv(i));
	}
	Com_Printf ("\n");
}

// Creates a new command that executes a command string (possibly ; seperated)
static void Cmd_Alias_f() {
	char cmd[1024] = {};

	if (cmd_argc == 1) {
		Com_Printf("Current alias commands:\n");
		for (cmdalias_t* a = cmd_alias; a; a = a->next) {
			Com_Printf ("%s : %s\n", a->name, a->value);
		}
		return;
	}

	char* s = Cmd_Argv(1);
	if (strlen(s) >= MAX_ALIAS_NAME) {
		Com_Printf ("Alias name is too long\n");
		return;
	}

	// if the alias already exists, reuse it
	cmdalias_t* a = cmd_alias;
	for (; a; a = a->next) {
		if (!strcmp(s, a->name)) {
			Z_Free (a->value);
			break;
		}
	}

	if (!a) {
		a = Z_Malloc (sizeof(cmdalias_t));
		a->next = cmd_alias;
		cmd_alias = a;
	}
	strcpy(a->name, s);

	// copy the rest of the command line
	int c = cmd_argc;
	for (int i = 2; i < c; i++) {
		strcat (cmd, Cmd_Argv(i));
		if (i != (c - 1)) {
			strcat (cmd, " ");
		}
	}
	strcat(cmd, "\n");

	a->value = CopyString(cmd);
}

static void Cmd_Wait_f() {
	cmd_wait = true;
}

static void Cmd_Cvar_Set_f() {
	if (cmd_argc == 4) {
		int flags = 0;
		if (!strcmp(Cmd_Argv(3), "u")) {
			flags = CVAR_USERINFO;
		}
		else if (!strcmp(Cmd_Argv(3), "s")) {
			flags = CVAR_SERVERINFO;
		} else {
			Com_Printf ("flags can only be 'u' or 's'\n");
			return;
		}
		COM_FullSetCvar (Cmd_Argv(1), Cmd_Argv(2), flags);
	} else if (cmd_argc == 3) {
		COM_SetCvar (Cmd_Argv(1), Cmd_Argv(2));
	} else {
		Com_Printf("usage: set <variable> <value> [u / s]\n");
	}
}

static void Cmd_Cvar_List_f() {

	int i = 0;
	for (cvar_t* var = cvar_vars ; var ; var = var->next, i++) {
		if (var->flags & CVAR_ARCHIVE) {
			Com_Printf ("*");
		} else {
			Com_Printf (" ");
		}

		if (var->flags & CVAR_USERINFO) {
			Com_Printf ("U");
		} else {
			Com_Printf (" ");
		}

		if (var->flags & CVAR_SERVERINFO) {
			Com_Printf ("S");
		} else {
			Com_Printf (" ");
		}

		if (var->flags & CVAR_NOSET) {
			Com_Printf ("-");
		} else if (var->flags & CVAR_LATCH) {
			Com_Printf ("L");
		} else {
			Com_Printf (" ");
		}

		Com_Printf (" %s \"%s\"\n", var->name, var->string);
	}

	Com_Printf ("%i cvars\n", i);
}

//
// SECTION Info strings
//

#define	MAX_INFO_KEY	64
#define	MAX_INFO_VALUE	64
#define	MAX_INFO_STRING	512

// Searches the string for the given key and returns the associated value, or an empty string.
static char* Info_ValueForKey(char *s, char *key) {
	static char value[2][512]; // use two buffers so compares work without stomping on each other
	static int valueindex = 0;
	valueindex ^= 1;

	if (*s == '\\') {
		s++;
	}

	char pkey[512] = {};
	for (;;) {
		char* o = pkey;
		while (*s != '\\') {
			if (!*s) {
				return "";
			}
			*o++ = *s++;
		}
		*o = 0;
		s++;

		o = value[valueindex];

		while (*s != '\\' && *s) {
			if (!*s) {
				return "";
			}
			*o++ = *s++;
		}
		*o = 0;

		if (!strcmp(key, pkey)) {
			return value[valueindex];
		}

		if (!*s) {
			return "";
		}
		s++;
	}
}

static void Info_RemoveKey(char *s, char *key) {
	char value[512];

	if (strstr (key, "\\")) {
		// Com_Printf ("Can't use a key with a \\\n");
		return;
	}

	char pkey[512];
	for (;;) {
		char* start = s;
		if (*s == '\\') {
			s++;
		}
		char* o = pkey;
		while (*s != '\\') {
			if (!*s) {
				return;
			}
			*o++ = *s++;
		}
		*o = 0;
		s++;

		o = value;
		while (*s != '\\' && *s) {
			if (!*s) {
				return;
			}
			*o++ = *s++;
		}
		*o = 0;

		if (!strcmp (key, pkey)) {
			strcpy (start, s); // remove this part
			return;
		}

		if (!*s) {
			return;
		}
	}
}

static void Info_SetValueForKey(char *s, char *key, char *value) {
	if (strstr(key, "\\") || strstr (value, "\\")) {
		Com_Printf("Can't use keys or values with a \\\n");
		return;
	}

	if (strstr(key, ";")) {
		Com_Printf("Can't use keys or values with a semicolon\n");
		return;
	}

	if (strstr (key, "\"") || strstr (value, "\"")) {
		Com_Printf("Can't use keys or values with a \"\n");
		return;
	}

	if (strlen(key) > MAX_INFO_KEY-1 || strlen(value) > MAX_INFO_KEY-1) {
		Com_Printf("Keys and values must be < 64 characters.\n");
		return;
	}
	Info_RemoveKey(s, key);
	if (!value || !strlen(value)) {
		return;
	}

	char newi[MAX_INFO_STRING];
	Com_sprintf(newi, sizeof(newi), "\\%s\\%s", key, value);

	if (strlen(newi) + strlen(s) > MAX_INFO_STRING) {
		Com_Printf("Info string length exceeded\n");
		return;
	}

	// only copy ascii values
	s += strlen(s);
	char* v = newi;
	while (*v) {
		int c = *v++;
		c &= 127; // strip high bits
		if (c >= 32 && c < 127)
			*s++ = c;
	}
	*s = 0;
}

// Some characters are illegal in info strings because they can mess up the server's parsing
static qboolean Info_Validate(char *s) {
	if (strstr (s, "\"")) {
		return false;
	}
	if (strstr (s, ";")) {
		return false;
	}
	return true;
}

static void Info_Print(char *s) {
	if (*s == '\\') {
		s++;
	}

	char key[512];
	char value[512];
	while (*s) {
		char* o = key;
		while (*s && *s != '\\') {
			*o++ = *s++;
		}

		int l = o - key;
		if (l < 20) {
			memset (o, ' ', 20 - l);
			key[20] = 0;
		} else {
			*o = 0;
		}
		Com_Printf ("%s", key);

		if (!*s) {
			Com_Printf ("MISSING VALUE\n");
			return;
		}

		o = value;
		s++;
		while (*s && *s != '\\') {
			*o++ = *s++;
		}
		*o = 0;

		if (*s) {
			s++;
		}
		Com_Printf ("%s\n", value);
	}
}

static char* Info_Cvar_Bit(int bit) {
	static char	info[MAX_INFO_STRING] = {};
	info[0] = 0;
	for (cvar_t* var = cvar_vars; var; var = var->next) {
		if (var->flags & bit) {
			Info_SetValueForKey(info, var->name, var->string);
		}
	}
	return info;
}

static char* Info_Cvar_User()	{return Info_Cvar_Bit(CVAR_USERINFO);}		// returns an info string containing all the CVAR_USERINFO cvars
static char* Info_Cvar_Server()	{return Info_Cvar_Bit(CVAR_SERVERINFO);}	// returns an info string containing all the CVAR_SERVERINFO cvars

//
// SECTION pak files
//

// The .pak files are just a linear collapse of a directory tree

#define	MAX_FILES_IN_PACK	4096
#define IDPAKHEADER			(('K'<<24)+('C'<<16)+('A'<<8)+'P')

typedef struct {
	char	name[56];
	int		filepos, filelen;
} dpackfile_t;

typedef struct {
	int		ident;		// == IDPAKHEADER
	int		dirofs;
	int		dirlen;
} dpackheader_t;

//
// SECTION pcx files
//

// PCX files are used for as many images as possible

typedef struct {
    char	manufacturer;
    char	version;
    char	encoding;
    char	bits_per_pixel;
    unsigned short	xmin,ymin,xmax,ymax;
    unsigned short	hres,vres;
    unsigned char	palette[48];
    char	reserved;
    char	color_planes;
    unsigned short	bytes_per_line;
    unsigned short	palette_type;
    char	filler[58];
    unsigned char	data; // unbounded
} pcx_t;


//
// SECTION md2 files
//

// .MD2 triangle model file format
// the glcmd format:
// a positive integer starts a tristrip command, followed by that many
// vertex structures.
// a negative integer starts a trifan command, followed by -x vertexes
// a zero indicates the end of the command list.
// a vertex consists of a floating point s, a floating point t,
// and an integer vertex index.

#define IDALIASHEADER		(('2'<<24)+('P'<<16)+('D'<<8)+'I')
#define ALIAS_VERSION	8

#define	MAX_TRIANGLES	4096
#define MAX_VERTS		2048
#define MAX_FRAMES		512
#define MAX_MD2SKINS	32
#define	MAX_SKINNAME	64

#define DTRIVERTX_V0   0
#define DTRIVERTX_V1   1
#define DTRIVERTX_V2   2
#define DTRIVERTX_LNI  3
#define DTRIVERTX_SIZE 4

typedef struct {
	short	s;
	short	t;
} dstvert_t;

typedef struct {
	short	index_xyz[3];
	short	index_st[3];
} dtriangle_t;

typedef struct {
	byte	v[3]; // scaled byte to fit in frame mins/maxs
	byte	lightnormalindex;
} dtrivertx_t;

typedef struct {
	float		scale[3];		// multiply byte verts by this
	float		translate[3];	// then add this
	char		name[16];		// frame name from grabbing
	dtrivertx_t	verts[1];		// variable sized
} daliasframe_t;

typedef struct {
	int			ident;
	int			version;

	int			skinwidth;
	int			skinheight;
	int			framesize;		// byte size of each frame

	int			num_skins;
	int			num_xyz;
	int			num_st;			// greater than num_xyz for seams
	int			num_tris;
	int			num_glcmds;		// dwords in strip/fan command list
	int			num_frames;

	int			ofs_skins;		// each skin is a MAX_SKINNAME string
	int			ofs_st;			// byte offset from start for stverts
	int			ofs_tris;		// offset for dtriangles
	int			ofs_frames;		// offset for first frame
	int			ofs_glcmds;
	int			ofs_end;		// end of file
} dmdl_t;

//
// SECTION sp2 files
//

// .SP2 sprite file format

#define IDSPRITEHEADER	(('2'<<24)+('S'<<16)+('D'<<8)+'I') // little-endian "IDS2"
#define SPRITE_VERSION	2

typedef struct {
	int		width, height;
	int		origin_x, origin_y;		// raster coordinates inside pic
	char	name[MAX_SKINNAME];		// name of pcx file
} dsprframe_t;

typedef struct {
	int			ident;
	int			version;
	int			numframes;
	dsprframe_t	frames[1];			// variable sized
} dsprite_t;

//
// SECTION wal files
//

// .WAL texture file format

#define	MIPLEVELS	4
typedef struct miptex_s {
	char		name[32];
	unsigned	width, height;
	unsigned	offsets[MIPLEVELS];		// four mip maps stored
	char		animname[32];			// next frame in animation chain
	int			flags;
	int			contents;
	int			value;
} miptex_t;

//
// SECTION bsp files
//

#define IDBSPHEADER	(('P'<<24)+('S'<<16)+('B'<<8)+'I') // little-endian "IBSP"
#define BSPVERSION	38

// upper design bounds
// leaffaces, leafbrushes, planes, and verts are still bounded by
// 16 bit short limits
#define	MAX_MAP_MODELS		1024
#define	MAX_MAP_BRUSHES		8192
#define	MAX_MAP_ENTITIES	2048
#define	MAX_MAP_ENTSTRING	0x40000
#define	MAX_MAP_TEXINFO		8192

#define	MAX_MAP_AREAS		256
#define	MAX_MAP_AREAPORTALS	1024
#define	MAX_MAP_PLANES		65536
#define	MAX_MAP_NODES		65536
#define	MAX_MAP_BRUSHSIDES	65536
#define	MAX_MAP_LEAFS		65536
#define	MAX_MAP_VERTS		65536
#define	MAX_MAP_FACES		65536
#define	MAX_MAP_LEAFFACES	65536
#define	MAX_MAP_LEAFBRUSHES 65536
#define	MAX_MAP_PORTALS		65536
#define	MAX_MAP_EDGES		128000
#define	MAX_MAP_SURFEDGES	256000
#define	MAX_MAP_LIGHTING	0x200000
#define	MAX_MAP_VISIBILITY	0x100000

// key / value pair sizes
#define	MAX_KEY		32
#define	MAX_VALUE	1024

#define	LUMP_ENTITIES		0
#define	LUMP_PLANES			1
#define	LUMP_VERTEXES		2
#define	LUMP_VISIBILITY		3
#define	LUMP_NODES			4
#define	LUMP_TEXINFO		5
#define	LUMP_FACES			6
#define	LUMP_LIGHTING		7
#define	LUMP_LEAFS			8
#define	LUMP_LEAFFACES		9
#define	LUMP_LEAFBRUSHES	10
#define	LUMP_EDGES			11
#define	LUMP_SURFEDGES		12
#define	LUMP_MODELS			13
#define	LUMP_BRUSHES		14
#define	LUMP_BRUSHSIDES		15
#define	LUMP_POP			16
#define	LUMP_AREAS			17
#define	LUMP_AREAPORTALS	18
#define	HEADER_LUMPS		19

// 0-2 are axial planes
#define	PLANE_X	0
#define	PLANE_Y	1
#define	PLANE_Z	2

// 3-5 are non-axial planes snapped to the nearest
#define	PLANE_ANYX 3
#define	PLANE_ANYY 4
#define	PLANE_ANYZ 5

// planes (x&~1) and (x&~1)+1 are always opposites

// contents flags are seperate bits
// a given brush can contribute multiple content bits
// multiple brushes can be in a single leaf

// lower bits are stronger, and will eat weaker brushes completely
#define	CONTENTS_SOLID			1 // an eye is never valid in a solid
#define	CONTENTS_WINDOW			2 // translucent, but not watery
#define	CONTENTS_AUX			4
#define	CONTENTS_LAVA			8
#define	CONTENTS_SLIME			16
#define	CONTENTS_WATER			32
#define	CONTENTS_MIST			64
#define	LAST_VISIBLE_CONTENTS	64

// remaining contents are non-visible, and don't eat brushes

#define	CONTENTS_AREAPORTAL		0x8000

#define	CONTENTS_PLAYERCLIP		0x10000
#define	CONTENTS_MONSTERCLIP	0x20000

// currents can be added to any other contents, and may be mixed
#define	CONTENTS_CURRENT_0		0x40000
#define	CONTENTS_CURRENT_90		0x80000
#define	CONTENTS_CURRENT_180	0x100000
#define	CONTENTS_CURRENT_270	0x200000
#define	CONTENTS_CURRENT_UP		0x400000
#define	CONTENTS_CURRENT_DOWN	0x800000

#define	CONTENTS_ORIGIN			0x1000000	// removed before bsping an entity

#define	CONTENTS_MONSTER		0x2000000	// should never be on a brush, only in game
#define	CONTENTS_DEADMONSTER	0x4000000
#define	CONTENTS_DETAIL			0x8000000	// brushes to be added after vis leafs
#define	CONTENTS_TRANSLUCENT	0x10000000	// auto set if any surface has trans
#define	CONTENTS_LADDER			0x20000000

// content masks
#define	MASK_SOLID				(CONTENTS_SOLID|CONTENTS_WINDOW)
#define	MASK_PLAYERSOLID		(CONTENTS_SOLID|CONTENTS_PLAYERCLIP|CONTENTS_WINDOW|CONTENTS_MONSTER)
#define	MASK_DEADSOLID			(CONTENTS_SOLID|CONTENTS_PLAYERCLIP|CONTENTS_WINDOW)
#define	MASK_MONSTERSOLID		(CONTENTS_SOLID|CONTENTS_MONSTERCLIP|CONTENTS_WINDOW|CONTENTS_MONSTER)
#define	MASK_WATER				(CONTENTS_WATER|CONTENTS_LAVA|CONTENTS_SLIME)
#define	MASK_OPAQUE				(CONTENTS_SOLID|CONTENTS_SLIME|CONTENTS_LAVA)
#define	MASK_SHOT				(CONTENTS_SOLID|CONTENTS_MONSTER|CONTENTS_WINDOW|CONTENTS_DEADMONSTER)
#define MASK_CURRENT			(CONTENTS_CURRENT_0|CONTENTS_CURRENT_90|CONTENTS_CURRENT_180|CONTENTS_CURRENT_270|CONTENTS_CURRENT_UP|CONTENTS_CURRENT_DOWN)

#define	SURF_LIGHT		0x1		// value will hold the light strength
#define	SURF_SLICK		0x2		// effects game physics
#define	SURF_SKY		0x4		// don't draw, but add to skybox
#define	SURF_WARP		0x8		// turbulent water warp
#define	SURF_TRANS33	0x10
#define	SURF_TRANS66	0x20
#define	SURF_FLOWING	0x40	// scroll towards angle
#define	SURF_NODRAW		0x80	// don't bother referencing the texture

#define	MAXLIGHTMAPS 4

#define	ANGLE_UP	-1
#define	ANGLE_DOWN	-2

// the visibility lump consists of a header with a count, then
// byte offsets for the PVS and PHS of each cluster, then the raw
// compressed bit vectors
#define	DVIS_PVS	0
#define	DVIS_PHS	1

typedef struct {
	int fileofs, filelen;
} lump_t;

typedef struct {
	int		ident;
	int		version;
	lump_t	lumps[HEADER_LUMPS];
} dheader_t;

typedef struct {
	float	mins[3], maxs[3];
	float	origin[3];		// for sounds or lights
	int		headnode;
	int		firstface, numfaces;	// submodels just draw faces without walking the bsp tree
} dmodel_t;

typedef struct {
	float point[3];
} dvertex_t;

typedef struct {
	float	normal[3];
	float	dist;
	int		type; // PLANE_X - PLANE_ANYZ ?remove? trivial to regenerate
} dplane_t;

typedef struct {
	int			planenum;
	int			children[2];	// negative numbers are -(leafs+1), not nodes
	short		mins[3];		// for frustom culling
	short		maxs[3];
	unsigned short	firstface;
	unsigned short	numfaces;	// counting both sides
} dnode_t;

typedef struct texinfo_s {
	float		vecs[2][4];		// [s/t][xyz offset]
	int			flags;			// miptex flags + overrides
	int			value;			// light emission, etc
	char		texture[32];	// texture name (textures/*.wal)
	int			nexttexinfo;	// for animations, -1 = end of chain
} texinfo_t;

// note that edge 0 is never used, because negative edge nums are used for
// counterclockwise use of the edge in a face
typedef struct {
	unsigned short v[2];		// vertex numbers
} dedge_t;

typedef struct {
	unsigned short	planenum;
	short		side;

	int			firstedge;		// we must support > 64k edges
	short		numedges;
	short		texinfo;

	// lighting info
	byte		styles[MAXLIGHTMAPS];
	int			lightofs;		// start of [numstyles*surfsize] samples
} dface_t;

typedef struct {
	int				contents;			// OR of all brushes (not needed?)

	short			cluster;
	short			area;

	short			mins[3];			// for frustum culling
	short			maxs[3];

	unsigned short	firstleafface;
	unsigned short	numleaffaces;

	unsigned short	firstleafbrush;
	unsigned short	numleafbrushes;
} dleaf_t;

typedef struct {
	unsigned short	planenum;		// facing out of the leaf
	short	texinfo;
} dbrushside_t;

typedef struct {
	int	firstside;
	int	numsides;
	int	contents;
} dbrush_t;

typedef struct {
	int	numclusters;
	int	bitofs[8][2];	// bitofs[numclusters][2]
} dvis_t;

// each area has a list of portals that lead into other areas
// when portals are closed, other areas may not be visible or
// hearable even if the vis info says that it should be
typedef struct {
	int		portalnum;
	int		otherarea;
} dareaportal_t;

typedef struct {
	int		numareaportals;
	int		firstareaportal;
} darea_t;

