// Writes key bindings and archived cvars to config.cfg
static void CL_WriteConfiguration() {
	if (cls.state == ca_uninitialized) {
		return;
	}

	char path[MAX_QPATH];
	Com_sprintf(path, sizeof(path),"%s/config.cfg", FS_Gamedir());

	{
		FILE* f = fopen(path, "w");
		if (!f) {
			Com_Printf("Couldn't write config.cfg.\n");
			return;
		}
		fprintf(f, "// generated by quake, do not modify\n");
		Key_WriteBindings(f);
		fclose (f);
	}

	// appends lines containing "set variable value" for all variables with the archive flag set to true.
	{
		char buffer[1024] = {};
		FILE* f = fopen(path, "a");
		for (cvar_t* var = cvar_vars ; var ; var = var->next) {
			if (var->flags & CVAR_ARCHIVE) {
				Com_sprintf(buffer, sizeof(buffer), "set %s \"%s\"\n", var->name, var->string);
				fprintf(f, "%s", buffer);
			}
		}
		fclose (f);
	}
}


/*
==================
CL_FixCvarCheats

==================
*/

typedef struct
{
	char	*name;
	char	*value;
	cvar_t	*var;
} cheatvar_t;

cheatvar_t	cheatvars[] = {
	{"timescale", "1"},
	{"timedemo", "0"},
	{"r_drawworld", "1"},
	{"cl_testlights", "0"},
	{"r_fullbright", "0"},
	{"r_drawflat", "0"},
	{"paused", "0"},
	{"fixedtime", "0"},
	{"sw_draworder", "0"},
	{"gl_lightmap", "0"},
	{"gl_saturatelighting", "0"},
	{NULL, NULL}
};

int		numcheatvars;

void CL_FixCvarCheats (void)
{
	int			i;
	cheatvar_t	*var;

	if ( !strcmp(cl.configstrings[CS_MAXCLIENTS], "1")
		|| !cl.configstrings[CS_MAXCLIENTS][0] )
		return;		// single player can cheat

	// find all the cvars if we haven't done it yet
	if (!numcheatvars)
	{
		while (cheatvars[numcheatvars].name)
		{
			cheatvars[numcheatvars].var = COM_GetCvar (cheatvars[numcheatvars].name,
					cheatvars[numcheatvars].value, 0);
			numcheatvars++;
		}
	}

	// make sure they are all set to the proper values
	for (i=0, var = cheatvars ; i<numcheatvars ; i++, var++)
	{
		if ( strcmp (var->var->string, var->value) )
		{
			COM_SetCvar (var->name, var->value);
		}
	}
}

